    "builderDescription": "Golden Homes is a sister company to Pyramid City. Our core business comprises residential as well as commercial property development in the major cities of Maharashtra. Pyramid City, already an established name in the market, has been around for more than a decade building landmark projects one after another through a decade-long trust of 1000s of families in the city.\r\nAfter the successful completion of our dream project pyramid city, our CEO Mr. Ashok Agrawal has decided to start Golden Homes brand with an aim to provide luxurious and quality lifestyle for all looking to fulfill their dream of extraordinary lifestyle. With making your dream as our passion to build extraordinary and beautiful projects, we promise to give you a great experience at Golden Homes.\r\nAt Golden Homes, we began our journey with one of its kind project in Shankarpur: a purely 42 Row Houses project with the name Luxury villas. With 25 outstanding amenities we aim to provide these 42 house owners a luxury living experience to have.\r\nWith our another successful commercial project running in Pune and our upcoming projects under both the brand names: Pyramid Gold and Golden Homes, we aim to cater all your needs under one umbrella. Pyramid Gold will be our landmark project consisting of 2BHK and 3BHK G+11 towers which will be launched in 2 phase manner and will take the sky lines of Nagpur city to new heights.\r\nWith Nagpur developing from all ways in the new so called green zone and to meet the increasing demand from upcoming hub of national IT companies in MIHAN as well as outstanding medical facilities like opening up of AIIMS and great education institution like IIM Nagpur, we promise to be a prominent player in the new rising sky lines of Nagpur city. With easy connectivity to locations like International Airport and Dmart, a 5 star hotel just a walk away from our project, it really gives a luxury in lifestyle for people staying in Golden Homes.",
