    "description": "The Empire by R Sandesh Group is an upcoming residential community on Kamptee Road, Nagpur, offering thoughtfully designed apartments for modern homebuyers. This under-construction project is planned to include every essential amenity and facility, ensuring a comfortable and convenient lifestyle. With well-crafted homes and a promising location, The Empire presents a refined living experience for families seeking quality and value.",
    "builderDescription": "At R Sandesh Group, we create landmarks that meet global standards, epitomise the values of our family, and are built on a legacy of loyalty spanning three decades. We are guided by our vision of ‘Building trust’. R Sandesh enables and transforms you to be a better version of yourself by maximising your potential and leading a fulfilling life.\r\n\r\nEvery project of our group delivers the highest level of design and craftsmanship, uncompromising quality, unparalleled service – getting us in the league of the world’s finest. Our homes are designed to enable more productivity, amenities designed and curated to equip with opportunity! Be it greens/open spaces designed to live a healthier and fuller life, banquets and club houses to network or striking the right chord with the right people, R Sandesh Group makes sure that your next biggest milestone is within reach.\r\n\r\nThe demand for medicines is always on an all-time high. Though there are enough supplies, sometimes one has to run pillar and post to the prescribed medicines as there's a rarity of it being not available at the nearby medical store. In such times a market which houses all the major wholesalers and suppliers of medicines come as the most useful resource as they stock almost every medicine which is unavailable elsewhere.\r\n\r\nThere is a growing need of having at least in such one-stop shop for all the medicinal requirements in every city and with that thought in mind R Sandesh Group developed the biggest Dawa Bazaar in the heart of Nagpur city, which is indeed a commendable move in itself.\r\n\r\nThe idea behind setting up these ventures was the growing need of medicines as Nagpur has become a medical hub for people coming in from Madhya Pradesh, Jharkhand and Chhattisgarh owing to its excellent healthcare services and medical supplies. Nagpur is one such city which offers cost-effective yet state-of-the-art medical treatment options, and this prompted the R Sandesh Group to think of a facility which would fulfil the ever-growing demand for medicinal supplies in the city which led to the establishment of these dawa bazaars.",
