    "isExclusive": false,
    "isRera": true,
    "towers": 2,
    "floors": 15,
    "description": "\"KANCHANGANGA LEGACY\" welcomes you. Within the contemporary city of Nagpur, this apartment is a welcome change. Although it is not so removed from daily life that you feel alone, it exudes a sense of calm and peace that you won't find so near a city anywhere else. The first impression is one of a warm welcome, and it starts at the apartment's ground floor main entrance. The word that immediately springs to mind is picturesque, and the sense of a perfect homecoming permeates the atmosphere. Why not? It's home, after all. Your ideal dream house.",
    "builderDescription": "Introducing The Builders Extraordinaire: Where Experience Meets Craftsmanship, and Dreams Find Their Home\r\n\r\nStep into a world where craftsmanship is an art form, experience is the foundation, and every project we undertake is a testament to our unwavering commitment to perfection. We are not just builders; we are dream-weavers, architects of happiness, and the creators of 1500 tales of fulfilled aspirations.\r\n\r\nIn our journey through the world of construction, we've not only constructed flats but sculpted dreams into reality.\r\n\r\nOur residential projects at Ramdaspeth, Dharampeth, Ram Nagar, Wanadongri have enabled us to understand various kinds of people and resonate with their needs. We have seen countless dreams getting fulfilled. We've had the privilege of witnessing the radiant smiles of countless families as they step into the homes they've longed for.\r\n\r\nOur experience is our cornerstone. After thousands of flats, we've learned that a home is more than just walls; it's a canvas for life's most cherished moments. It's where children grow, where laughter resounds, and where legacies are born.\r\n\r\nYet, what sets us apart is our passion. We don't just build structures; we build futures. Our team, driven by the love for our craft, pours heart and soul into each project. We create not just flats, but sanctuaries where dreams can thrive.\r\n\r\nAs we move forward, we carry with us the wisdom of the past and the promise of the future. We pledge to continue crafting not just buildings, but havens where life unfolds in all its glory.\r\n\r\nWelcome to a world where experience and expertise blend seamlessly, where your dream home is more than a structure; it's a legacy waiting to be lived. Join us as we embark on another chapter, where your dreams will become our masterpiece.\"",
